const branchScope = (req: Request, alias: string) => {
  const selected = Number(req.query.branch_id) || 0;
  if (selected && !['SUPER_ADMIN'].includes(String(req.user?.role)) && !(req.user?.role === 'ADMIN' && !(req.user?.branch_ids ?? []).length)) {
    return (req.user?.branch_ids ?? []).includes(selected) ? { sql: ` AND ${alias}.branch_id=?`, params: [selected] } : { sql: ' AND 1=0', params: [] as number[] };
  }
  if (['SUPER_ADMIN'].includes(String(req.user?.role)) || (req.user?.role === 'ADMIN' && !(req.user?.branch_ids ?? []).length)) return selected ? { sql: ` AND ${alias}.branch_id=?`, params: [selected] } : { sql: '', params: [] as number[] };
  const ids = req.user?.branch_ids ?? [];
  return ids.length
    ? { sql: ` AND ${alias}.branch_id IN (${ids.map(() => '?').join(',')})`, params: ids }
    : { sql: ' AND 1=0', params: [] as number[] };
};
const asyncRoute = (fn: (req: Request, res: Response) => Promise<void>) => (req: Request, res: Response, next: NextFunction) => fn(req, res).catch(next);
const ensureJobBranchAccess = asyncRoute(async (req, res) => {
  if (['SUPER_ADMIN'].includes(String(req.user?.role))) return;
  const jobCardId = req.params.jobCardId;
  const receiptId = req.params.id;
  const rows = receiptId
    ? await query<RowDataPacket & { branch_id: number }>('SELECT j.branch_id FROM payment_receipts p JOIN job_cards j ON j.id=p.job_card_id WHERE p.id=? AND p.company_id=? AND j.deleted_at IS NULL', [receiptId, req.user!.company_id])
    : await query<RowDataPacket & { branch_id: number }>('SELECT j.branch_id FROM job_cards j WHERE j.id=? AND j.company_id=? AND j.deleted_at IS NULL', [jobCardId, req.user!.company_id]);
  const scope = branchScope(req, 'j');
  if (!rows[0] || (scope.sql && !(req.user?.branch_ids ?? []).includes(Number(rows[0].branch_id)))) {
    res.status(404).json({ message: 'Record not found for your assigned branch' });
    return;
  }
});
