router.get('/lookups/:type', asyncRoute(async (req, res) => {
    const s = `%${String(req.query.search ?? '').trim()}%`;
    const map: Record<string, string> = {
        vehicles: `SELECT v.*,c.name customer_name,c.mobile customer_mobile FROM vehicles v LEFT JOIN customers c ON c.id=v.customer_id AND c.company_id=v.company_id WHERE v.company_id=? AND v.status='active' AND (v.vehicle_number LIKE ? OR v.vehicle_name LIKE ? OR v.model LIKE ? OR v.engine_number LIKE ?) ORDER BY v.vehicle_number LIMIT 20`,
        customers: `SELECT m.* FROM customers m WHERE m.company_id=? AND m.status='active' AND (m.name LIKE ? OR m.mobile LIKE ? OR m.contact_person LIKE ?) ORDER BY m.name LIMIT 20`,
        vendors: `SELECT * FROM vendors WHERE company_id=? AND status='active' AND (code LIKE ? OR name LIKE ? OR mobile LIKE ? OR gstin LIKE ?) ORDER BY name LIMIT 20`,
        employees: `SELECT e.*,CONCAT_WS(' ',e.first_name,e.last_name) full_name,d.name department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id AND d.company_id=e.company_id WHERE e.company_id=? AND e.status='active' AND (e.code LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR e.mobile LIKE ?) ORDER BY e.first_name LIMIT 20`,
        products: `SELECT p.*,u.code uom_code,u.name uom_name FROM products p JOIN uoms u ON u.id=p.uom_id AND u.company_id=p.company_id WHERE p.company_id=? AND p.status='active' AND (p.code LIKE ? OR p.name LIKE ? OR p.part_number LIKE ?) ORDER BY p.name LIMIT 20`,
        'pending-statuses': `SELECT * FROM work_pending_sub_statuses WHERE company_id=? AND status='active' AND (code LIKE ? OR name LIKE ?) ORDER BY name LIMIT 20`
    };
    let sql = map[req.params.type];
    if (!sql) {
        res.status(404).json({ message: 'Lookup not found' });
        return;
    }
    const scopedType = ['vehicles', 'customers', 'employees'].includes(req.params.type);
    const scope = scopedType ? branchScope(req, req.params.type === 'vehicles' ? 'v' : req.params.type === 'employees' ? 'e' : 'm') : { sql: '', params: [] as number[] };
    if (scope.sql) sql = sql.replace(req.params.type === 'vehicles' ? "v.status='active'" : req.params.type === 'employees' ? "e.status='active'" : "status='active'", `${req.params.type === 'vehicles' ? "v.status='active'" : req.params.type === 'employees' ? "e.status='active'" : "status='active'"}${scope.sql}`);
    const count = (sql.match(/LIKE \?/g) || []).length;
    res.json({ data: await query<RowDataPacket & Record<string, unknown>>(sql, [req.user!.company_id, ...scope.params, ...Array(count).fill(s)]) });
}));
