const jobSelect = `SELECT j.*,f.name financial_year_name,b.name branch_name,v.vehicle_number,v.vehicle_name,v.model vehicle_model,v.manufacturing_year vehicle_manufacturing_year,v.fuel_type vehicle_fuel_type,v.engine_number vehicle_engine_number,v.chassis_number vehicle_chassis,c.name customer_name,c.mobile customer_mobile,cu.full_name created_by_name,au.full_name approved_by_name,w.id work_order_id,w.work_order_no FROM job_cards j JOIN financial_years f ON f.id=j.financial_year_id JOIN branches b ON b.id=j.branch_id JOIN vehicles v ON v.id=j.vehicle_id JOIN customers c ON c.id=j.customer_id JOIN users cu ON cu.id=j.created_by LEFT JOIN users au ON au.id=j.approved_by LEFT JOIN work_orders w ON w.job_card_id=j.id AND w.deleted_at IS NULL`;
